/// Returns a broadcast [Stream] of events from the `signals` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<PlatformSignal> signals( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel signalsChannel =
      EventChannel('dev.flutter.pigeon.sherpa_platform.SherpaPlatformEventApi.signals$instanceName', pigeonMethodCodec);
  return signalsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as PlatformSignal;
  });
